    // Process 6: requires 2^1, 3^1
    while (true) {
        if ((primeExponents[2] ?: 0) >= 1 && (primeExponents[3] ?: 0) >= 1) {
            digits.add(6)
            primeExponents[2] = primeExponents[2]!! - 1
            primeExponents[3] = primeExponents[3]!! - 1
        } else {
            break
        }
    }

    // Process 5: requires 5^1
    while (true) {
        if ((primeExponents[5] ?: 0) >= 1) {
            digits.add(5)
            primeExponents[5] = primeExponents[5]!! - 1
        } else {
            break
        }
    }

    // Process 4: requires 2^2
    while (true) {
        if ((primeExponents[2] ?: 0) >= 2) {
            digits.add(4)
            primeExponents[2] = primeExponents[2]!! - 2
        } else {
            break
        }
    }

    // Process 3: requires 3^1
    while (true) {
        if ((primeExponents[3] ?: 0) >= 1) {
            digits.add(3)
            primeExponents[3] = primeExponents[3]!! - 1
        } else {
            break
        }
    }

    // Process 2: requires 2^1
    while (true) {
        if ((primeExponents[2] ?: 0) >= 1) {
            digits.add(2)
            primeExponents[2] = primeExponents[2]!! - 1
        } else {
            break
        }
    }

    digits.sortDescending()

    val result = digits.joinToString("")
    println(result)
}

fun factorize(d: Int): Map<Int, Int> {
    val factors = mutableMapOf<Int, Int>()
    when (d) {
        2 -> factors[2] = 1
        3 -> factors[3] = 1
        4 -> { factors[2] = 3 }
        5 -> factors[5] = 1
        6 -> { factors[2] = 1; factors[3] = 1 }
        7 -> factors[7] = 1
        8 -> { factors[2] = 3 }
        9 -> { factors[2] = 1; factors[3] = 2 }
    }
    return factors
}
